import * as React from "react";

export type ImageItem = {
  src: string;
  alt?: string;
  caption?: string;
};

type ImageModalProps = {
  images: ImageItem[];
  trigger: (open: (startIndex?: number) => void) => React.ReactNode;
  initialIndex?: number;
};

const clampIndex = (index: number, total: number) => {
  if (total === 0) return 0;
  return ((index % total) + total) % total;
};

const ImageModal: React.FC<ImageModalProps> = ({
  images,
  trigger,
  initialIndex = 0,
}) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(
    clampIndex(initialIndex, images.length)
  );

  const handleOpen = (startIndex: number = initialIndex) => {
    if (images.length === 0) return;
    setActiveIndex(clampIndex(startIndex, images.length));
    setIsOpen(true);
  };

  const handleClose = () => setIsOpen(false);

  const handlePrev = () =>
    setActiveIndex((prev) => clampIndex(prev - 1, images.length));
  const handleNext = () =>
    setActiveIndex((prev) => clampIndex(prev + 1, images.length));

  React.useEffect(() => {
    if (!isOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen]);

  React.useEffect(() => {
    if (!isOpen) return;
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [isOpen]);

  const showNav = images.length > 1;
  const current = images[activeIndex];

  return (
    <>
      {trigger(handleOpen)}
      {isOpen && current && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-popup_overlay"
          onClick={handleClose}
          role="presentation"
        >
          <div
            className="relative w-[88vw] max-w-[980px] bg-beige-500 border border-dark_gray-200 shadow-xl"
            onClick={(event) => event.stopPropagation()}
            role="dialog"
            aria-modal="true"
          >
            <button
              type="button"
              aria-label="Close"
              onClick={handleClose}
              className="absolute -top-4 -right-4 h-10 w-10 rounded-sm bg-terracota text-lg font-marcellus-sc-sans shadow-md"
            >
              <img
                src="/close.png"
                alt="Close button"
                width={42}
                height={43}
                className="w-[62.5%] mx-auto"
                decoding="async"
              />
            </button>
            {showNav && (
              <>
                <button
                  type="button"
                  aria-label="Previous image"
                  onClick={handlePrev}
                  className="absolute left-3 top-auto bottom-6 z-10 flex h-10 w-10 items-center justify-center rounded-full border border-dark_gray-200 bg-warm_ivory text-terracota-500 shadow-md md:-left-14 md:top-1/2 md:-translate-y-1/2 md:bottom-auto"
                >
                <img
                  src="/nav_button.png"
                  alt="Previous image button"
                  width={25}
                  height={40}
                  className="w-[40%] -ml-1 rotate-180"
                  decoding="async"
                />
                </button>
                <button
                  type="button"
                  aria-label="Next image"
                  onClick={handleNext}
                  className="absolute right-3 top-auto bottom-6 z-10 flex h-10 w-10 items-center justify-center rounded-full border border-dark_gray-200 bg-warm_ivory text-terracota-500 shadow-md md:-right-14 md:top-1/2 md:-translate-y-1/2 md:bottom-auto"
                >
                <img
                  src="/nav_button.png"
                  alt="Previous image button"
                  width={25}
                  height={40}
                  className="w-[40%] ml-1"
                  decoding="async"
                />
                </button>
              </>
            )}
            <div className="flex h-full flex-col">
              <div className="flex-1 bg-warm_ivory-500 p-4 md:p-6">
                <img
                  src={current.src}
                  alt={current.alt ?? ""}
                  className="h-full w-full object-contain max-h-[600px]"
                />
              </div>
              {current.caption && (
                <div className="border-t border-dark_gray-200 bg-beige-500 px-16 sm:px-4 py-2 text-center font-marcellus-sc text-[11px] uppercase tracking-[2px] text-terracota-500 md:text-[12px]">
                  {current.caption}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ImageModal;
