// src/components/SEO.tsx
import React from "react";
import type { Company } from "../interfaces";

interface Props {
  data: Company;
  localesData?: string | Record<string, unknown>;
  language?: string;
  languages?: string[];
  defaultLanguage?: string;
  originalPath?: string;

  titleKey?: string;
  descriptionKey?: string;
  authorKey?: string;

  title?: string;
  description?: string;
  author?: string;

  /**
   * Optional overrides for canonical and social
   */
  pathname?: string; // you can still override manually if needed
  canonical?: string; // full override (absolute URL)
  image?: string; // absolute URL preferred
  noindex?: boolean;

  /**
   * Schema overrides
   */
  schemaType?: "LocalBusiness" | "ProfessionalService" | "Organization";
  schemaName?: string;

  /**
   * Add extra JSON-LD schemas (e.g., FAQPage for blog posts)
   */
  additionalSchemas?: object | object[];
}

const DEFAULT_OG_IMAGE = "https://chestercourt.com/logo.png";

function stripTrailingSlash(url: string) {
  return url.replace(/\/+$/, "");
}

function ensureLeadingSlash(path: string) {
  if (!path) return "/";
  return path.startsWith("/") ? path : `/${path}`;
}

function stripQueryAndHash(path: string) {
  return path.split("?")[0].split("#")[0];
}

function ensureTrailingSlash(path: string) {
  if (!path) return "/";
  return path.endsWith("/") ? path : `${path}/`;
}

function isAbsoluteUrl(url?: string) {
  return !!url && /^https?:\/\//i.test(url);
}

function parseLocales(localesData?: string | Record<string, unknown>) {
  if (!localesData) return undefined;
  if (typeof localesData === "string") {
    try {
      return JSON.parse(localesData) as Record<string, unknown>;
    } catch {
      return undefined;
    }
  }
  return localesData;
}

function getByPath(
  source: Record<string, unknown> | undefined,
  path?: string
): string | undefined {
  if (!source || !path) return undefined;
  const value = path
    .split(".")
    .reduce<unknown>((acc, part) => {
      if (!acc || typeof acc !== "object") return undefined;
      return (acc as Record<string, unknown>)[part];
    }, source);

  return typeof value === "string" ? value : undefined;
}

const SEO: React.FC<Props> = ({
  data,
  localesData,
  language,
  languages,
  defaultLanguage,
  originalPath,
  titleKey,
  descriptionKey,
  authorKey,
  title,
  description,
  author,
  pathname,
  canonical,
  image,
  noindex,
  schemaType = "LocalBusiness",
  schemaName,
  additionalSchemas,
}) => {
  const translations = parseLocales(localesData);
  const resolvedLanguage = language || "en";
  const resolvedDefaultLanguage = defaultLanguage || resolvedLanguage;
  const resolvedLanguages =
    languages && languages.length > 0 ? languages : [resolvedLanguage];

  const resolvedTitle =
    title ?? getByPath(translations, titleKey) ?? titleKey ?? data.companyName;

  const resolvedDescription =
    description ??
    getByPath(translations, descriptionKey) ??
    descriptionKey ??
    "";

  const resolvedAuthor =
    author ??
    getByPath(translations, authorKey) ??
    data.companyName ??
    "";

  const siteUrl = stripTrailingSlash((data?.url || "").trim());

  const baseOriginalPath = ensureTrailingSlash(
    stripQueryAndHash(ensureLeadingSlash(originalPath || pathname || "/"))
  );

  const autoLocalizedPath =
    resolvedLanguage === resolvedDefaultLanguage
      ? baseOriginalPath
      : ensureTrailingSlash(`/${resolvedLanguage}${baseOriginalPath}`);

  const finalPath = ensureTrailingSlash(
    stripQueryAndHash(ensureLeadingSlash(pathname ?? autoLocalizedPath))
  );

  const resolvedCanonical =
    canonical ?? (siteUrl ? `${siteUrl}${finalPath}` : undefined);

  const ogImage = isAbsoluteUrl(image)
    ? image
    : image && siteUrl
      ? `${siteUrl}${ensureLeadingSlash(image)}`
      : DEFAULT_OG_IMAGE;

  const hrefLangLinks =
    siteUrl && resolvedLanguages?.length
      ? resolvedLanguages.map((lng) => {
          const hrefPath =
            lng === resolvedDefaultLanguage
              ? baseOriginalPath
              : ensureTrailingSlash(`/${lng}${baseOriginalPath}`);

          return (
            <link
              key={lng}
              rel="alternate"
              hrefLang={lng}
              href={`${siteUrl}${hrefPath}`}
            />
          );
        })
      : null;

  const xDefaultHref =
    siteUrl && resolvedDefaultLanguage
      ? `${siteUrl}${baseOriginalPath}`
      : undefined;

  const schemaMarkup = {
    "@context": "https://schema.org",
    "@type": schemaType,
    name: schemaName || data.companyName || "Code Crafted Studios",
    image: ogImage,
    address: {
      "@type": "PostalAddress",
      streetAddress: data.address,
      addressLocality: data.city,
      addressRegion: data.province,
      postalCode: data.postalCode,
      addressCountry: data.country === "Canada" ? "CA" : data.country,
    },
    geo: {
      "@type": "GeoCoordinates",
      latitude: 45.35475,
      longitude: -73.7376551,
    },
    url: resolvedCanonical,
    telephone: data.phone,
    priceRange: "$$",
    openingHours: "Mo-Fr 09:00-17:00",
    sameAs: [data.instagram, data.facebook, data.linkedin].filter(Boolean),
  };

  const extras = Array.isArray(additionalSchemas)
    ? additionalSchemas
    : additionalSchemas
      ? [additionalSchemas]
      : [];


      
  return (
    <>
      <html lang={resolvedLanguage} />
      <title>{resolvedTitle}</title>
      <meta name="description" content={resolvedDescription} />
      {resolvedAuthor ? <meta name="author" content={resolvedAuthor} /> : null}

      {/* Canonical */}
      {resolvedCanonical ? <link rel="canonical" href={resolvedCanonical} /> : null}

      {/* hreflang alternates */}
      {hrefLangLinks}
      {xDefaultHref ? (
        <link rel="alternate" hrefLang="x-default" href={xDefaultHref} />
      ) : null}

      {/* Robots */}
      {noindex ? <meta name="robots" content="noindex, nofollow" /> : null}

      {/* Open Graph */}
      <meta property="og:type" content="website" />
      <meta property="og:title" content={resolvedTitle} />
      <meta property="og:description" content={resolvedDescription} />
      {resolvedCanonical ? <meta property="og:url" content={resolvedCanonical} /> : null}
      {ogImage ? <meta property="og:image" content={ogImage} /> : null}

      {/* Twitter */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={resolvedTitle} />
      <meta name="twitter:description" content={resolvedDescription} />
      {ogImage ? <meta name="twitter:image" content={ogImage} /> : null}

      {/* Structured Data (base) */}
      <script type="application/ld+json">{JSON.stringify(schemaMarkup)}</script>

      {/* Structured Data (extras) */}
      {extras.map((schema, idx) => (
        <script key={idx} type="application/ld+json">
          {JSON.stringify(schema)}
        </script>
      ))}
    </>
  );
};

export default SEO;
